import * as motion from "motion/react-client";
import { navlink as quicklink } from "../../lib/portfolio/data/navlink";
import { Mail } from "lucide-react";
import Container from "../../components/portfolio/container";
import { Suspense } from "react";
import { currentYear } from "../../lib/portfolio/utils";
import Image from "next/image";


function Footer() {
 const llms = [
   {
     id: "llms-file",
     title: "llms.txt",
     url: "/llms.txt",
     icon: "llms.txt",
     hoverColor: "hover:text-blue-400",
     bgColor: "bg-blue-400/10",
     description: "Explore the llms.txt file...",
   },
 ];
  return (
    <footer className="mt-20 border-t border-zinc-900  selection:bg-blue-600 selection:text-white overflow-hidden">
      <div className="h-0.5 bg-linear-to-r from-transparent via-accent-purple/35 to-transparent w-full" />

      <Container>
        <ShipItCTA />

        <div className="grid grid-cols-1 md:grid-cols-2 gap-0 border-b border-zinc-900">
          <motion.div
            initial={{ opacity: 0, y: 50 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6 }}
            className="p-8 space-y-6 border-b md:border-b-0 md:border-r border-zinc-900"
          >
            <Image
              src="/portfolio/lettermark.svg"
              width={162}
              height={46}
              alt="lettermark"
              className="h-8 w-auto"
            />
            <p className="text-gray-400 text-sm leading-relaxed">
              Building immersive digital experiences optimized for speed and
              accessibility. Specializing in conversion-focused design and
              robust software engineering.
            </p>
            <a
              href="mailto:contact@rajeevpuri.com.np"
              className="inline-flex items-center text-white hover:text-blue-400 transition-colors duration-300 group"
            >
              <Mail className="w-5 h-5 mr-2 group-hover:scale-110 transition-transform" />
              <span className="text-sm font-medium">
                contact@rajeevpuri.com.np
              </span>
            </a>
          </motion.div>

          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.2 }}
            className="p-8  space-y-6 border-b md:border-b-0 border-border"
          >
            <h3 className="text-white text-xl font-semibold">Quick Links</h3>
            <nav className="grid grid-cols-2 gap-2">
              {[...quicklink, ...llms].map((link) => (
                <motion.a
                  key={link.id}
                  href={link.url}
                  className="flex items-center text-gray-400 hover:text-white transition-colors duration-300"
                  whileHover={{ x: 4 }}
                >
                  <span>{link.title}</span>
                </motion.a>
              ))}
            </nav>
          </motion.div>


        </div>

        <div className="px-8  py-10">
          <div className="flex flex-col md:flex-row justify-between items-center gap-6">
            <Suspense>
              <p className="text-gray-400 text-xs md:text-sm">
                &copy; {currentYear} Rajeev Puri. All rights reserved.
              </p>
            </Suspense>

            <nav className="flex gap-4 flex-wrap justify-center md:justify-end">
              {[...quicklink, ...llms].map((link) => (
                <motion.a
                  key={link.id}
                  href={link.url}
                  className="flex items-center text-gray-400 hover:text-white transition-colors duration-300"
                  whileHover={{ x: 4 }}
                >
                  <span>{link.title}</span>
                </motion.a>
              ))}
            </nav>
          </div>
        </div>
      </Container>
    </footer>
  );
}

function ShipItCTA() {
  return (
    <section className="py-2 group overflow-hidden border-b border-zinc-900">
      <motion.div
        initial={{ opacity: 0, y: 30 }}
        whileInView={{ opacity: 1, y: 0 }}
        viewport={{ once: true }}
        className="relative z-10 px-6 text-5xl sm:text-6xl md:text-7xl lg:text-9xl"
      >
        <h2 className="font-black tracking-wide leading-tight md:leading-none select-none transition-all duration-700 ">
          <span className="text-white block md:inline md:mx-2">SAY IT.</span>

          <span className="text-zinc-800 block md:inline md:mx-2">SHARE IT.</span>

          <span className="text-blue-600 block md:inline md:mx-2">SHIP IT.</span>
        </h2>
      </motion.div>
    </section>
  );
}

export default Footer;

import { cn } from "../../lib/portfolio/utils";
import * as motion from "motion/react-client";
import { ReactNode } from "react";

interface ContainerProps {
  id?: string;
  children: ReactNode;
  className?: string;
  variants?: any;
  initial?: any;
  animate?: any;
  transition?: any;
}

export default function Container({
  id,
  children,
  className,
  variants,
  initial = "hidden",
  animate = "visible",
  transition,
}: Readonly<ContainerProps>) {
  return (
    <motion.section
      id={id}
      className={cn(className, "max-w-6xl mx-auto overflow-x-hidden")}
      variants={variants}
      initial={initial}
      animate={animate}
      transition={transition}
    >
      {children}
    </motion.section>
  );
}

@theme inline {
  --color-primary-light: var(--primary);
  --color-primary-hover: var(--primary);
  --color-accent-cyan: var(--secondary);
  --color-accent-purple: var(--primary);
  --color-info: var(--primary);
  --shadow-glow: 0 0 20px color-mix(in oklab, var(--primary) 15%, transparent);
  --shadow-glow-lg: 0 0 30px color-mix(in oklab, var(--primary) 25%, transparent);
  --font-heading: var(--font-sans);
}

@layer components {
  /* Example utility combining the new theme variables */
  .btn-primary-glow {
    @apply bg-primary text-primary-foreground shadow-glow hover:shadow-glow-lg
           transition-all duration-200 active:scale-95;
  }

  .blog-content > table,
  .blog-content > .table-wrapper > table {
    width: 100%;
    margin: 2rem 0;
    border-collapse: separate;
    border-spacing: 0;
    overflow: hidden;
    border: 1px solid var(--border);
    background: color-mix(in oklab, var(--background) 60%, transparent);
    box-shadow: 0 1px 2px rgb(0 0 0 / 0.08);
    font-size: 0.95rem;
  }

  .blog-content > table[header-row="true"] tbody tr:first-child td,
  .blog-content > table thead th,
  .blog-content > .table-wrapper > table[header-row="true"] tbody tr:first-child td,
  .blog-content > .table-wrapper > table thead th {
    background: color-mix(in oklab, var(--muted) 40%, transparent);
    color: var(--foreground);
    font-size: 0.625rem;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
  }

  .blog-content > table td,
  .blog-content > table th,
  .blog-content > .table-wrapper > table td,
  .blog-content > .table-wrapper > table th {
    padding: 0.9rem 1rem;
    border-bottom: 1px solid var(--border);
    text-align: left;
    vertical-align: top;
    color: var(--muted-foreground);
  }

  .blog-content > table tr:last-child td,
  .blog-content > table tr:last-child th,
  .blog-content > .table-wrapper > table tr:last-child td,
  .blog-content > .table-wrapper > table tr:last-child th {
    border-bottom: 0;
  }

  .blog-content > table td code,
  .blog-content > table th code,
  .blog-content > .table-wrapper > table td code,
  .blog-content > .table-wrapper > table th code {
    display: inline-block;
    padding: 0.1rem 0.35rem;
    border-radius: calc(var(--radius) * 0.45);
    background: var(--muted);
    color: var(--foreground);
    font-family: var(--font-sans);
    font-size: 0.85em;
    font-weight: 600;
  }


}

interface QuickLink {
  id: string;
  title: string;
  url: string;
}
export const navlink: QuickLink[] = [
  {
    id: "projects",
    title: "Projects",
    url: "/projects",
  },

  {
    id: "about",
    title: "About",
    url: "/about",
  },
  {
    id: "contact",
    title: "Contact",
    url: "/contact",
  },
  {
    id: "blog",
    title: "Blog",
    url: "/blog",
  },
];

export { cn } from "cn"

export const currentYear = new Date().getFullYear().toString();
export function formatDate(date: string | Date): string {
  const dateObj = typeof date === "string" ? new Date(date) : date
  return new Intl.DateTimeFormat("en-US", {
    year: "numeric",
    month: "long",
    day: "numeric",
  }).format(dateObj)
}
